//! Black and theta over the whole input domain, against random
//! high-precision references (`scripts/pricing_domain_reference.py`): 400
//! Black prices with F and K across the f64 range, near and far from the
//! money, and w from 1e-38 to 1e5; 160 thetas on a flat surface, with
//! r = q, r = 0 and q = 0 among them. Every case is within 1e-12 relative.

#![cfg(feature = "options")]
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::excessive_precision
)]

use std::str::FromStr;

use market_maker_rs::Decimal;
use market_maker_rs::options::pricing::{Dynamics, OptionInputs, black_undiscounted, value};
use market_maker_rs::options::surface::FlatSurface;
use optionstratlib::OptionStyle;
use rust_decimal::prelude::ToPrimitive;

const TOLERANCE: f64 = 1e-12;

fn style(call: bool) -> OptionStyle {
    if call {
        OptionStyle::Call
    } else {
        OptionStyle::Put
    }
}

#[test]
fn test_black_matches_high_precision_over_the_domain() {
    for &(fwd, strike, w, call, want) in BLACK {
        let got = black_undiscounted(fwd, strike, w, style(call)).unwrap();
        let rel = ((got - want) / want).abs();
        assert!(
            rel <= TOLERANCE,
            "F {fwd:e} K {strike:e} w {w:e} call {call}: {got:e} vs {want:e} (rel {rel:e})"
        );
    }
}

#[test]
fn test_theta_matches_high_precision_over_the_domain() {
    for &(s, k, tau, r, q, sigma, call, want) in THETA {
        let d = |x: &str| Decimal::from_str(x).unwrap();
        let flat = FlatSurface::new(d(sigma)).unwrap();
        let inputs = OptionInputs::european(d(s), d(k), d(tau), d(r), d(q), style(call));
        let got = value(&inputs, &flat, Dynamics::StickyMoneyness)
            .unwrap()
            .theta
            .to_f64()
            .unwrap();
        let rel = ((got - want) / want).abs();
        assert!(
            rel <= TOLERANCE,
            "S {s} K {k} tau {tau} r {r} q {q} sigma {sigma} call {call}: {got:e} vs {want:e} (rel {rel:e})"
        );
    }
}

